package com.meteorsss.startrace;
import android.graphics.*;
import android.view.View;
import java.util.*;
public final class Charts extends View {
    private final MainActivity a;private final Ui u;private final String kind;private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);
    private final long track;private final Store.Place destination;private long loaded;private List<TrackPoint> points=Collections.emptyList();
    public Charts(MainActivity a,String kind,long track,Store.Place place){super(a);this.a=a;u=a.u;this.kind=kind;this.track=track;destination=place;setLayerType(View.LAYER_TYPE_SOFTWARE,null);setContentDescription(kind.equals("sky")?"卫星天空图":kind.equals("signal")?"卫星信号强度图":kind.equals("track")?"无底图轨迹预览":"指南针");}
    private void line(Canvas c,float x,float y,float x2,float y2,int color,float width){p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(u.dp(width));c.drawLine(x,y,x2,y2,p);p.setStyle(Paint.Style.FILL);}
    private void label(Canvas c,String text,float x,float y,int color,int size,Paint.Align align){p.setStyle(Paint.Style.FILL);p.setTextSize(u.dp(size));p.setColor(color);p.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));p.setTextAlign(align);c.drawText(text,x,y,p);}
    private void circle(Canvas c,float x,float y,float r,int color,boolean fill){p.setStyle(fill?Paint.Style.FILL:Paint.Style.STROKE);p.setColor(color);p.setStrokeWidth(u.dp(1));c.drawCircle(x,y,r,p);p.setStyle(Paint.Style.FILL);}
    @Override protected void onDraw(Canvas c){super.onDraw(c);switch(kind){case "sky":sky(c);break;case "signal":signals(c);break;case "track":track(c);break;default:compass(c);}}
    private void sky(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(cx,cy)-u.dp(24);for(int i=1;i<=3;i++)circle(c,cx,cy,r*i/3,u.border,false);line(c,cx-r,cy,cx+r,cy,u.border,1);line(c,cx,cy-r,cx,cy+r,u.border,1);label(c,"N",cx,cy-r-u.dp(8),u.accent,13,Paint.Align.CENTER);label(c,"S",cx,cy+r+u.dp(17),u.muted,12,Paint.Align.CENTER);label(c,"W",cx-r-u.dp(12),cy+u.dp(4),u.muted,12,Paint.Align.CENTER);label(c,"E",cx+r+u.dp(12),cy+u.dp(4),u.muted,12,Paint.Align.CENTER);Set<String> drawn=new HashSet<>();for(GnssEngine.Satellite s:a.e.currentSatellites()){if(!drawn.add(s.key()))continue;float rr=r*(1-s.elevation/90f);float x=cx+(float)Math.sin(Math.toRadians(s.azimuth))*rr,y=cy-(float)Math.cos(Math.toRadians(s.azimuth))*rr;int color=u.constellation(s.system);boolean used=s.used;for(GnssEngine.Satellite other:a.e.currentSatellites())if(other.key().equals(s.key())&&other.used)used=true;circle(c,x,y,u.dp(7),color,used);label(c,""+s.id,x,y-u.dp(11),color,10,Paint.Align.CENTER);}if(drawn.isEmpty())label(c,"等待卫星数据",cx,cy-u.dp(8),u.muted,14,Paint.Align.CENTER);}
    private void signals(Canvas c){List<GnssEngine.Satellite> list=a.e.currentSatellites();int n=Math.min(20,list.size());if(n==0){label(c,"暂无信号记录",getWidth()/2f,u.dp(35),u.muted,14,Paint.Align.CENTER);return;}float left=u.dp(110),right=getWidth()-u.dp(40);for(int i=0;i<n;i++){GnssEngine.Satellite s=list.get(i);float y=u.dp(17+i*34);label(c,s.label(),0,y,u.text,11,Paint.Align.LEFT);String freq=s.hasFrequency?String.format(Locale.US,"%.2f MHz",s.frequency/1e6):"频率未提供";label(c,freq,0,y+u.dp(12),u.muted,9,Paint.Align.LEFT);line(c,left,y-2,right,y-2,u.border,5);line(c,left,y-2,left+(right-left)*Math.min(1,s.cn0/60),y-2,u.constellation(s.system),5);label(c,String.format(Locale.US,"%.0f",s.cn0),getWidth(),y+2,s.used?u.accent:u.muted,12,Paint.Align.RIGHT);}}
    private void track(Canvas c){long now=android.os.SystemClock.elapsedRealtime();if(now-loaded>3000||loaded==0){points=a.app.store.preview(track,1200);loaded=now;}for(int i=1;i<5;i++){line(c,getWidth()*i/5f,0,getWidth()*i/5f,getHeight(),u.border,.5f);line(c,0,getHeight()*i/5f,getWidth(),getHeight()*i/5f,u.border,.5f);}label(c,"N ↑",u.dp(10),u.dp(20),u.muted,11,Paint.Align.LEFT);if(points.isEmpty()){label(c,"等待有效轨迹点",getWidth()/2f,getHeight()/2f,u.muted,14,Paint.Align.CENTER);return;}TrackPoint origin=points.get(0);double cos=Math.cos(Math.toRadians(origin.lat)),xmin=0,xmax=0,ymin=0,ymax=0;double[] xs=new double[points.size()],ys=new double[points.size()];for(int i=0;i<points.size();i++){TrackPoint v=points.get(i);double dl=((v.lon-origin.lon+540)%360)-180;xs[i]=dl*cos*111195;ys[i]=-(v.lat-origin.lat)*111195;xmin=Math.min(xmin,xs[i]);xmax=Math.max(xmax,xs[i]);ymin=Math.min(ymin,ys[i]);ymax=Math.max(ymax,ys[i]);}double scale=Math.min((getWidth()-u.dp(52))/Math.max(20,xmax-xmin),(getHeight()-u.dp(64))/Math.max(20,ymax-ymin));float px=0,py=0;int seg=-1;for(int i=0;i<points.size();i++){float x=(float)(getWidth()/2.0+(xs[i]-(xmin+xmax)/2)*scale),y=(float)(getHeight()/2.0+(ys[i]-(ymin+ymax)/2)*scale);if(seg==points.get(i).segment)line(c,px,py,x,y,u.accent,2.5f);if(i==0)circle(c,x,y,u.dp(5),u.warning,true);if(i==points.size()-1)circle(c,x,y,u.dp(6),u.accent,true);px=x;py=y;seg=points.get(i).segment;}label(c,"相对轨迹 · 非道路地图",getWidth()/2f,getHeight()-u.dp(10),u.muted,10,Paint.Align.CENTER);}
    private void compass(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(cx,cy)-u.dp(30);float heading=destination==null?a.e.magneticHeading:a.e.trueHeading();circle(c,cx,cy,r,u.border,false);if(Float.isNaN(heading)){label(c,"等待方向数据",cx,cy,u.muted,14,Paint.Align.CENTER);return;}c.save();c.rotate(-heading,cx,cy);for(int deg=0;deg<360;deg+=5){double angle=Math.toRadians(deg);float inner=r-u.dp(deg%30==0?15:7);line(c,cx+(float)Math.sin(angle)*inner,cy-(float)Math.cos(angle)*inner,cx+(float)Math.sin(angle)*r,cy-(float)Math.cos(angle)*r,deg==0?u.accent:u.border,deg%30==0?2:1);}String[] directions={"N","E","S","W"};for(int i=0;i<4;i++){double v=Math.toRadians(i*90);label(c,directions[i],cx+(float)Math.sin(v)*(r-u.dp(33)),cy-(float)Math.cos(v)*(r-u.dp(33))+u.dp(5),i==0?u.accent:u.text,16,Paint.Align.CENTER);}c.restore();float arrow=0;if(destination!=null&&a.e.fresh())arrow=(float)(Geo.bearing(a.e.location.getLatitude(),a.e.location.getLongitude(),destination.lat,destination.lon)-heading);c.save();c.rotate(arrow,cx,cy);Path path=new Path();path.moveTo(cx,cy-r*.48f);path.lineTo(cx-u.dp(14),cy+u.dp(22));path.lineTo(cx,cy+u.dp(12));path.lineTo(cx+u.dp(14),cy+u.dp(22));path.close();p.setColor(u.accent);c.drawPath(path,p);c.restore();label(c,String.format(Locale.US,"%.0f°",heading),cx,cy+r*.62f,u.text,24,Paint.Align.CENTER);}
}